// 1. a retry that can double-charge
fun charge(conn: Connection, cardId: Long, merchantId: Long, amount: Long): Long {
    repeat(3) {
        try {
            val id = insertPayment(conn, cardId, merchantId, amount)   // payment_uid DEFAULT uuidv7()
            conn.commit()                                            // may succeed, then lose its reply
            return id
        } catch (e: SQLException) {
            conn.rollback()                                          // and try again: a second charge
        }
    }
    error("charge failed")
}

// 2. the same key on every attempt
fun insertOnce(conn: Connection, key: UUID, cardId: Long, merchantId: Long, amount: Long): Long =
    conn.prepareStatement(
        """
        INSERT INTO payments (payment_uid, card_id, merchant_id, amount_minor, status, created_at)
        VALUES (?, ?, ?, ?, 'succeeded', now())
        ON CONFLICT (payment_uid) DO NOTHING
        RETURNING payment_id
        """,
    ).use { ps ->
        ps.setObject(1, key); ps.setLong(2, cardId); ps.setLong(3, merchantId); ps.setLong(4, amount)
        ps.executeQuery().use { rs -> if (rs.next()) rs.getLong(1) else null }
    } ?: paymentIdOf(conn, key)                           // already charged: the first attempt's row

// 3. which failures to retry
fun retryable(e: SQLException): Boolean = when {
    e.sqlState == "40001" || e.sqlState == "40P01" -> true   // aborted: nothing happened
    e.sqlState?.startsWith("08") == true -> true              // connection lost: unknown, the key makes it safe
    else -> false                                              // 23505, 23514...: the same every time
}

// 4. the charge, retried safely
fun charge(pool: DataSource, key: UUID, cardId: Long, merchantId: Long, amount: Long): Long {
    var attempt = 1
    while (true) {
        try {
            return pool.connection.use { conn ->
                conn.autoCommit = false
                insertOnce(conn, key, cardId, merchantId, amount).also { conn.commit() }
            }
        } catch (e: SQLException) {
            if (!retryable(e) || attempt == 4) throw e
            Thread.sleep(50L shl attempt++)                    // 100, 200, 400 ms
        }
    }
}
// only now: send the receipt for payment_uid = key
